mapper.sql:
WHERE a.del_yn = 'N'

    AND a.concurrent_key IS NOT NULL
    AND a.concurrent_key IS NULL

AND (p.name_ko ILIKE '%' || #{keyword} || '%' OR a.employee_no ILIKE '%' || #{keyword} || '%')
AND a.person_key = #{personKey}
AND a.concurrent_key = #{concurrentKey}
AND a.dept_cd = #{deptCd}
AND a.grade_code = #{gradeCode}
AND a.assignment_type_code = #{assignmentTypeCode}
AND a.assignment_date >= #{assignmentDateFrom}
AND a.assignment_date <= #{assignmentDateTo}

mapper.select:
SELECT ORDER BY
a.assignment_order a.employee_no p.name_ko a.dept_cd a.grade_code a.assignment_type_code a.assignment_date
ASCDESC, a.assignment_date DESC, a.assignment_order DESC, a.assignment_key ASC LIMIT #{limit} OFFSET #{offset}
